# Test SRV, TXT etc with same manual
def query(name, qtype):
    import socket, struct
    def build(name, qtype):
        parts=name.strip(".").split(".")
        qname=b"".join(bytes([len(p)])+p.encode() for p in parts)+b"\x00"
        header=struct.pack("!HHHHHH", 0x1234, 0x0100, 1,0,0,1)
        question=qname+struct.pack("!HH", qtype, 1)
        opt=b"\x00\x00\x29\x10\x00\x00\x00\x00\x00\x00\x00"
        return header+question+opt
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.settimeout(2)
    s.sendto(build(name,qtype), ("10.0.0.2",53))
